def has_cycle_of_length_at_most(edges, n, max_len):
    """Check if graph has any cycle of length <= max_len"""
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex, but we need to detect cycles of length <= max_len
    # For each vertex, run DFS up to depth max_len
    for start in range(n):
        # Use stack for DFS: (node, parent, depth)
        stack = [(start, -1, 0)]
        visited = {start: 0}
        while stack:
            v, p, d = stack.pop()
            for w in adj[v]:
                if w == p:
                    continue
                if w in visited:
                    # cycle found
                    cycle_len = visited[v] + visited[w] + 1
                    if cycle_len <= max_len:
                        return True
                else:
                    if d + 1 < max_len:
                        visited[w] = d + 1
                        stack.append((w, v, d+1))
        # Actually this approach may not detect all cycles correctly.
        # Let's use a simpler method: enumerate all simple paths up to length max_len and check for cycles.
    return False

def has_cycle_of_length_at_most_brute(edges, n, max_len):
    """Brute force check for cycles up to length max_len"""
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # For each vertex, do DFS limited depth
    for start in range(n):
        stack = [(start, [start])]
        while stack:
            v, path = stack.pop()
            if len(path) > max_len + 1:
                continue
            for w in adj[v]:
                if w == start and len(path) >= 3 and len(path) <= max_len:
                    # cycle found
                    return True
                if w not in path:
                    stack.append((w, path + [w]))
    return False

def is_3_colorable(edges, n):
    """Check if graph is 3-colorable using simple backtracking"""
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        # Try colors 0,1,2
        used = {colors[u] for u in adj[v] if colors[u] != -1}
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

