def random_search(n_vertices, target_edges, max_girth=7, max_attempts=10000):
    for attempt in range(max_attempts):
        # Start with a random tree (ensures connectivity, not required but helps)
        edges = []
        # Build random tree
        vertices = list(range(n_vertices))
        random.shuffle(vertices)
        for i in range(1, n_vertices):
            u = vertices[i]
            v = random.choice(vertices[:i])
            edges.append((min(u,v), max(u,v)))

        # Add random edges up to target
        all_possible = [(i,j) for i in range(n_vertices) for j in range(i+1, n_vertices)]
        random.shuffle(all_possible)
        for e in all_possible:
            if len(edges) >= target_edges:
                break
            if e not in edges:
                edges.append(e)

        # Trim to target edges
        if len(edges) > target_edges:
            edges = edges[:target_edges]
        elif len(edges) < target_edges:
            continue

        # Check constraints
        if has_cycle_of_length_at_most_brute(edges, n_vertices, 6):
            continue
        if is_3_colorable(edges, n_vertices):
            return edges
    return None

